const jobs = $input.all();

/*
 * V1.1 — Pre-filter
 *
 * Objectif :
 * - conserver les postes explicitement AI / GenAI / automation
 * - conserver les intitulés techniques susceptibles de cacher de l'AI
 * - conserver les postes compatibles avec le profil Data/AI
 * - éviter les offres clairement senior
 * - privilégier France / Europe / Remote pertinent
 *
 * Ce filtre doit rester permissif :
 * Gemini prend la décision finale.
 */

// ---------------------------------------------------------
// 1. Signaux AI / GenAI / Agentic AI
// ---------------------------------------------------------

const aiSignals = [
  "artificial intelligence",
  "intelligence artificielle",
  "generative ai",
  "genai",
  "gen ai",
  "ia générative",
  "llm",
  "large language model",
  "large language models",

  "ai agent",
  "ai agents",
  "agentic ai",
  "agentic",
  "agentique",
  "multi-agent",
  "multi agent",

  "rag",
  "retrieval augmented generation",

  "langgraph",
  "langchain",

  "model context protocol",
  "mcp",

  "prompt engineering",
  "prompt engineer",

  "ai automation",
  "intelligent automation",
  "ai-powered automation",
  "ai powered automation",

  "machine learning",
  "ml engineer",
  "mlops",

  "vertex ai",
  "gemini"
];


// ---------------------------------------------------------
// 2. Titres intéressants même sans "AI"
// ---------------------------------------------------------

const relevantTitleSignals = [
  // AI / ML
  "ai engineer",
  "ia engineer",
  "genai engineer",
  "machine learning",
  "ml engineer",
  "mlops",
  "data scientist",

  // Data
  "data engineer",
  "analytics engineer",

  // Software / Backend
  "software engineer",
  "software developer",
  "backend engineer",
  "backend developer",
  "back-end",
  "développeur",
  "developer",

  // Automation / Integration
  "automation engineer",
  "integration engineer",
  "integration developer",
  "intelligent automation",

  // Solutions / Forward deployed
  "solutions engineer",
  "solution engineer",
  "forward deployed",
  "implementation engineer",
  "technical consultant",
  "consultant technique",

  // Cloud / Platform
  "cloud engineer",
  "platform engineer"
];


// ---------------------------------------------------------
// 3. Compétences techniques proches du profil
// ---------------------------------------------------------

const technicalSignals = [
  "python",
  "fastapi",

  "api integration",
  "api integrations",
  "api integration",
  "intégration api",
  "rest api",

  "workflow automation",
  "workflow orchestration",
  "automation workflow",
  "automatisation",
  "orchestration",

  "docker",

  "gcp",
  "google cloud",
  "vertex ai",

  "airflow",
  "cloud composer",

  "dbt",

  "etl",
  "elt",

  "bigquery",

  "rag",
  "langgraph",
  "mcp"
];


// ---------------------------------------------------------
// 4. Localisations compatibles
// ---------------------------------------------------------

const compatibleLocations = [
  "france",
  "paris",
  "lyon",
  "rennes",
  "lille",
  "toulouse",
  "bordeaux",
  "nantes",
  "marseille",
  "montpellier",
  "grenoble",
  "nice",
  "sophia antipolis",

  // Certaines offres européennes peuvent être remote France
  "europe",
  "emea",

  "remote france",
  "remote - france",
  "france - remote"
];


// ---------------------------------------------------------
// 5. Localisations clairement incompatibles
// ---------------------------------------------------------

const incompatibleLocations = [
  "united states",
  "usa",
  "u.s.",
  "canada",

  "australia",
  "singapore",
  "india",

  "brazil",
  "mexico"
];


// ---------------------------------------------------------
// 6. Signaux de forte séniorité
// ---------------------------------------------------------

const seniorTitleSignals = [
  "senior ",
  "sr.",
  "sr ",
  "staff ",
  "principal ",
  "lead ",
  "director",
  "head of",
  "vp ",
  "vice president",
  "manager"
];


// ---------------------------------------------------------
// Analyse
// ---------------------------------------------------------

return jobs.map(item => {

  const job = item.json;

  const title = String(job.title ?? "").toLowerCase();
  const description = String(job.description ?? "").toLowerCase();
  const location = String(job.location ?? "").toLowerCase();

  const fullText = `${title} ${description}`;


  // ---------- AI ----------

  const matchedAiSignals = aiSignals.filter(signal =>
    fullText.includes(signal)
  );


  // ---------- TITLE ----------

  const matchedTitleSignals = relevantTitleSignals.filter(signal =>
    title.includes(signal)
  );


  // ---------- TECH ----------

  const matchedTechnicalSignals = technicalSignals.filter(signal =>
    description.includes(signal)
  );


  // ---------- LOCATION ----------

  const matchedCompatibleLocations =
    compatibleLocations.filter(signal =>
      location.includes(signal)
    );

  const matchedIncompatibleLocations =
    incompatibleLocations.filter(signal =>
      location.includes(signal)
    );


  // ---------- SENIORITY ----------

  const matchedSeniorSignals =
    seniorTitleSignals.filter(signal =>
      title.includes(signal)
    );

  const clearlySenior =
    matchedSeniorSignals.length > 0;


  // -------------------------------------------------------
  // Géographie
  // -------------------------------------------------------

  let locationCompatible = true;

  // Une localisation explicitement incompatible bloque
  // l'offre sauf si France/Europe apparaît également.
  if (
    matchedIncompatibleLocations.length > 0 &&
    matchedCompatibleLocations.length === 0
  ) {
    locationCompatible = false;
  }


  // -------------------------------------------------------
  // Pertinence métier
  // -------------------------------------------------------

  const hasStrongAiSignal =
    matchedAiSignals.length > 0;

  const hasRelevantTitle =
    matchedTitleSignals.length > 0;

  const hasTechnicalFit =
    matchedTechnicalSignals.length >= 2;


  /*
   * IMPORTANT :
   *
   * On accepte :
   * - AI explicite
   * OU
   * - titre potentiellement hidden-AI
   * OU
   * - plusieurs signaux techniques pertinents
   */

  const roleRelevant =
    hasStrongAiSignal ||
    hasRelevantTitle ||
    hasTechnicalFit;


  // -------------------------------------------------------
  // Décision finale du préfiltre
  // -------------------------------------------------------

  const passPreFilter =
    roleRelevant &&
    locationCompatible &&
    !clearlySenior;


  return {
    json: {
      ...job,

      pre_filter: {

        ai_signals:
          matchedAiSignals,

        title_signals:
          matchedTitleSignals,

        technical_signals:
          matchedTechnicalSignals,

        compatible_location_signals:
          matchedCompatibleLocations,

        incompatible_location_signals:
          matchedIncompatibleLocations,

        senior_signals:
          matchedSeniorSignals,

        has_ai_signal:
          hasStrongAiSignal,

        potential_hidden_ai:
          !hasStrongAiSignal && hasRelevantTitle,

        location_compatible:
          locationCompatible,

        clearly_senior:
          clearlySenior
      },

      pass_pre_filter:
        passPreFilter
    }
  };

});

const raw = $json.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error("Gemini returned an empty response.");
}

let analysis;

try {
  analysis = JSON.parse(raw);
} catch (error) {
  throw new Error(`Invalid JSON returned by Gemini: ${raw}`);
}

// Retrieve the original job linked to the current Gemini item
const job = $("Loop Over Items").item.json;

return {
  json: {
    job: {
      source: job.source,
      source_id: job.source_id,
      title: job.title,
      company: job.company,
      location: job.location,
      team: job.team,
      contract_type: job.contract_type,
      description: job.description,
      job_url: job.job_url,
      apply_url: job.apply_url,
      collected_at: job.collected_at
    },

    analysis: {
      ai_automation_relevance:
        Number(analysis.ai_automation_relevance ?? 0),

      junior_compatibility:
        Number(analysis.junior_compatibility ?? 0),

      candidate_fit:
        Number(analysis.candidate_fit ?? 0),

      hidden_ai_automation_role:
        analysis.hidden_ai_automation_role === true,

      matched_skills:
        Array.isArray(analysis.matched_skills)
          ? analysis.matched_skills
          : [],

      missing_skills:
        Array.isArray(analysis.missing_skills)
          ? analysis.missing_skills
          : [],

      experience_required:
        analysis.experience_required ?? "Not explicitly specified",

      reason:
        analysis.reason ?? "",

      recommendation:
        analysis.recommendation ?? "REVIEW"
    }
  }
};

