parameters.jsCode:
const input = $input.all();

const normalized = [];

for (const item of input) {
  // Selon la façon dont n8n restitue la réponse Greenhouse :
  // soit chaque item est déjà un job,
  // soit le premier item contient { jobs: [...] }
  const jobs = Array.isArray(item.json.jobs)
    ? item.json.jobs
    : [item.json];

  for (const job of jobs) {
    if (!job?.id || !job?.title) continue;

    // Greenhouse peut renvoyer du HTML dans "content"
    const description = (job.content ?? "")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/li>/gi, "\n")
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/\s+/g, " ")
      .trim();

    normalized.push({
      json: {
        source: "greenhouse",
        source_id: String(job.id),
        title: job.title ?? null,
        company: "Talkdesk",
        location: job.location?.name ?? null,
        team: null,
        contract_type: null,
        description,
        job_url: job.absolute_url ?? null,
        apply_url: job.absolute_url ?? null,
        collected_at: new Date().toISOString()
      }
    });
  }
}

return normalized;
